INSERT INTO `uied_banner` VALUES (1,'cmk10u2rg00013k5168ovvcs9','测试',NULL,NULL,NULL,'_blank','html','<style>\n.uied-banner-carousel {\n  width: 100%;\n  height: 48px;\n  border-radius: 12px;\n  overflow: hidden;\n  position: relative;\n}\n\n.uied-banner-slide {\n  position: absolute;\n  inset: 0;\n  display: none;\n  align-items: center;\n  justify-content: center;\n  text-decoration: none;\n  background-size: cover;\n  background-position: center;\n  padding: 0 8px;\n}\n\n.uied-banner-slide.is-active {\n  display: flex;\n}\n\n.uied-banner-nav-btn {\n  position: absolute;\n  top: 50%;\n  transform: translateY(-50%);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  width: 28px;\n  height: 28px;\n  border: none;\n  background: rgba(255, 255, 255, 0.6);\n  backdrop-filter: blur(4px);\n  -webkit-backdrop-filter: blur(4px);\n  border-radius: 50%;\n  cursor: pointer;\n  transition: all 0.2s ease;\n  padding: 0;\n  z-index: 10;\n}\n\n.uied-banner-nav-btn:hover {\n  background: rgba(255, 255, 255, 0.9);\n}\n\n.uied-banner-nav-btn svg {\n  width: 14px;\n  height: 14px;\n  color: #333;\n}\n\n.uied-banner-nav-prev {\n  left: 8px;\n}\n\n.uied-banner-nav-next {\n  right: 8px;\n}\n\n.uied-banner-content {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 8px;\n  padding: 0 40px;\n  max-width: 100%;\n}\n\n.uied-banner-badge {\n  background: rgba(255, 255, 255, 0.5);\n  backdrop-filter: blur(4px);\n  -webkit-backdrop-filter: blur(4px);\n  padding: 2px 8px;\n  border-radius: 4px;\n  font-size: 12px;\n  color: #333;\n  font-weight: 700;\n  border: 1px solid rgba(0, 0, 0, 0.1);\n  white-space: nowrap;\n  flex: 0 0 auto;\n}\n\n.uied-banner-text {\n  font-size: 15px;\n  font-weight: 600;\n  color: #000;\n  letter-spacing: 0.5px;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.uied-banner-link-icon {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  width: 20px;\n  height: 20px;\n  flex-shrink: 0;\n}\n\n.uied-banner-link-icon svg {\n  width: 14px;\n  height: 14px;\n  color: rgba(0, 0, 0, 0.6);\n  transition: transform 0.2s ease;\n}\n\n.uied-banner-slide:hover .uied-banner-link-icon svg {\n  transform: translateX(2px);\n}\n</style>\n\n<div class=\"uied-banner-carousel\" id=\"uiedBannerCarousel\">\n  <button class=\"uied-banner-nav-btn uied-banner-nav-prev\" onclick=\"event.preventDefault();event.stopPropagation();uiedBannerPrev();\" title=\"上一个\">\n    <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke=\"currentColor\" stroke-width=\"2\">\n      <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M15 19l-7-7 7-7\" />\n    </svg>\n  </button>\n  <button class=\"uied-banner-nav-btn uied-banner-nav-next\" onclick=\"event.preventDefault();event.stopPropagation();uiedBannerNext();\" title=\"下一个\">\n    <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke=\"currentColor\" stroke-width=\"2\">\n      <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M9 5l7 7-7 7\" />\n    </svg>\n  </button>\n  \n  <a class=\"uied-banner-slide is-active\" href=\"https://fsuied.com/website-scmz.html\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"background-image: linear-gradient(to right, rgb(99, 102, 241) 0%, rgb(224, 231, 255) 35%, rgb(237, 242, 255) 45%, rgb(139, 92, 246) 100%);\">\n    <span class=\"uied-banner-content\">\n      <span class=\"uied-banner-badge\">推荐</span>\n      <span class=\"uied-banner-text\">无需代码 会打字就能轻松建网站</span>\n      <span class=\"uied-banner-link-icon\"><svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke=\"currentColor\" stroke-width=\"2\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14\" /></svg></span>\n    </span>\n  </a>\n  <a class=\"uied-banner-slide\" href=\"https://nf.video/mbx1u6/?gid=18\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"background-image: linear-gradient(to right, rgb(236, 72, 153) 0%, rgb(251, 231, 239) 35%, rgb(253, 242, 248) 45%, rgb(244, 114, 182) 100%);\">\n    <span class=\"uied-banner-content\">\n      <span class=\"uied-banner-badge\">热门</span>\n      <span class=\"uied-banner-text\">GPT-5.2重回巅峰 智能对话</span>\n      <span class=\"uied-banner-link-icon\"><svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke=\"currentColor\" stroke-width=\"2\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14\" /></svg></span>\n    </span>\n  </a>\n  <a class=\"uied-banner-slide\" href=\"https://www.trae.com.cn/?utm_source=advertising&utm_medium=uied_ug_cpa&utm_term=hw_trae_uied\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"background-image: linear-gradient(to right, rgb(168, 85, 247) 0%, rgb(243, 232, 255) 35%, rgb(245, 243, 255) 45%, rgb(192, 132, 252) 100%);\">\n    <span class=\"uied-banner-content\">\n      <span class=\"uied-banner-badge\">新品</span>\n      <span class=\"uied-banner-text\">免费AI编程工具 Trae - 智能编码助手</span>\n      <span class=\"uied-banner-link-icon\"><svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke=\"currentColor\" stroke-width=\"2\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14\" /></svg></span>\n    </span>\n  </a>\n  <a class=\"uied-banner-slide\" href=\"https://yuanbao.paluai.com/uied\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"background-image: linear-gradient(to right, rgb(255, 200, 0) 0%, rgb(255, 237, 153) 35%, rgb(255, 248, 204) 45%, rgb(255, 170, 0) 100%);\">\n    <span class=\"uied-banner-content\">\n      <span class=\"uied-banner-badge\">新品</span>\n      <span class=\"uied-banner-text\">腾讯元宝 智能对话新体验</span>\n      <span class=\"uied-banner-link-icon\"><svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke=\"currentColor\" stroke-width=\"2\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14\" /></svg></span>\n    </span>\n  </a>\n  <a class=\"uied-banner-slide\" href=\"https://www.aippt.cn/?utm_type=Navweb&utm_source=bbdh&utm_page=aippt&utm_plan=ppt&utm_unit=AIPPT&utm_keyword=40471047\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"background-image: linear-gradient(to right, rgb(16, 185, 129) 0%, rgb(209, 250, 229) 35%, rgb(236, 253, 245) 45%, rgb(52, 211, 153) 100%);\">\n    <span class=\"uied-banner-content\">\n      <span class=\"uied-banner-badge\">高效</span>\n      <span class=\"uied-banner-text\">免费AI生成PPT - 一键生成演示文稿</span>\n      <span class=\"uied-banner-link-icon\"><svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke=\"currentColor\" stroke-width=\"2\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14\" /></svg></span>\n    </span>\n  </a>\n  <a class=\"uied-banner-slide\" href=\"https://universalbus.cn/?s=lPLG02aydo\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"background-image: linear-gradient(to right, rgb(249, 115, 22) 0%, rgb(255, 237, 213) 35%, rgb(255, 247, 237) 45%, rgb(251, 146, 60) 100%);\">\n    <span class=\"uied-banner-content\">\n      <span class=\"uied-banner-badge\">特惠</span>\n      <span class=\"uied-banner-text\">Adobe 正版全家桶可用AI</span>\n      <span class=\"uied-banner-link-icon\"><svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke=\"currentColor\" stroke-width=\"2\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14\" /></svg></span>\n    </span>\n  </a>\n  <a class=\"uied-banner-slide\" href=\"https://universalbus.cn/?s=lPLG02aydo\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"background-image: linear-gradient(to right, rgb(14, 165, 233) 0%, rgb(224, 242, 254) 35%, rgb(240, 249, 255) 45%, rgb(56, 189, 248) 100%);\">\n    <span class=\"uied-banner-content\">\n      <span class=\"uied-banner-badge\">新品</span>\n      <span class=\"uied-banner-text\">Gemini3 可用 nanobanana</span>\n      <span class=\"uied-banner-link-icon\"><svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke=\"currentColor\" stroke-width=\"2\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14\" /></svg></span>\n    </span>\n  </a>\n</div>\n\n<script>\n(function () {\n  var root = document.getElementById(\"uiedBannerCarousel\");\n  if (!root) return;\n  var slides = root.querySelectorAll(\".uied-banner-slide\");\n  if (!slides || slides.length <= 1) return;\n  var index = 0;\n  var intervalMs = 4000;\n  var timer;\n\n  function show(i) {\n    for (var k = 0; k < slides.length; k++) {\n      slides[k].classList.toggle(\"is-active\", k === i);\n    }\n  }\n\n  function next() {\n    index = (index + 1) % slides.length;\n    show(index);\n  }\n\n  function prev() {\n    index = (index - 1 + slides.length) % slides.length;\n    show(index);\n  }\n\n  function startTimer() {\n    timer = setInterval(next, intervalMs);\n  }\n\n  function resetTimer() {\n    clearInterval(timer);\n    startTimer();\n  }\n\n  window.uiedBannerNext = function() {\n    next();\n    resetTimer();\n  };\n\n  window.uiedBannerPrev = function() {\n    prev();\n    resetTimer();\n  };\n\n  startTimer();\n})();\n</script>\n',NULL,'top,bottom',0,1,NULL,NULL,7,0,1767609126,1768579992,0);
